"""Migration of legacy OPP_MASTER validation rules from opportunity_rules.vrl."""

from decimal import Decimal
from typing import Any


def _text(value: Any) -> str:
    """Return the legacy text representation for missing/null text fields."""
    return "" if value is None else str(value)


def _nvl(value: Any, default: Any) -> Any:
    """Implement legacy NVL: empty, missing, and null values use the default."""
    return default if value is None or value == "" else value


def _number(value: Any) -> Decimal:
    """Coerce legacy NUMBER values; empty values compare as zero."""
    value = _nvl(value, 0)
    return Decimal(str(value))


def _date_ge(left: Any, right: Any) -> bool:
    """Legacy date >= comparison, including the 00000000 no-value sentinel."""
    left_text = _text(left)
    right_text = _text(right)
    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def _failure(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {"code": code, "message": message, "severity": severity}


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an OPP_MASTER post-write image using legacy VRL rule order."""
    errors: list[dict] = []
    old_record = old if event == "UPDATE" and old is not None else {}

    amt = record.get("AMT", "")
    stat_cd = _text(record.get("STAT_CD", ""))
    lost_rsn = _text(record.get("LOST_RSN", ""))
    close_dt = _text(record.get("CLOSE_DT", ""))
    stage_pct = record.get("STAGE_PCT", "")

    # OPP-001: INSERT, UPDATE
    if event in ("INSERT", "UPDATE") and not (_number(_nvl(amt, 0)) >= Decimal(0)):
        errors.append(_failure("E3001", "Amount negative"))

    # OPP-002: INSERT, UPDATE
    if event in ("INSERT", "UPDATE") and not (
        not (stat_cd == "W" and _number(_nvl(amt, 0)) == Decimal(0))
    ):
        errors.append(_failure("E3002", "Won opportunity requires amount"))

    # OPP-003: INSERT, UPDATE
    if event in ("INSERT", "UPDATE") and not (
        not (stat_cd == "L" and lost_rsn == "")
    ):
        errors.append(_failure("E3003", "Lost reason required"))

    # OPP-004: INSERT, UPDATE
    if event in ("INSERT", "UPDATE") and not (
        not (stat_cd == "W" and close_dt == "00000000")
    ):
        errors.append(_failure("E3004", "Won opportunity requires close date"))

    # OPP-005: UPDATE
    if event == "UPDATE" and not (
        not (_text(old_record.get("STAT_CD", "")) == "W" and stat_cd != "W")
    ):
        errors.append(_failure("E3005", "Cannot reopen a won opportunity"))

    # OPP-006: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        stage = _number(stage_pct)
        valid_stage = (
            (stat_cd == "P" and stage == Decimal(10))
            or (stat_cd == "Q" and stage == Decimal(25))
            or (stat_cd == "N" and stage == Decimal(60))
            or (stat_cd == "W" and stage == Decimal(100))
            or (stat_cd == "L" and stage == Decimal(0))
        )
        if not valid_stage:
            errors.append(_failure("E3006", "Stage percent inconsistent with status"))

    # OPP-007: INSERT
    if event == "INSERT" and not (
        close_dt == "00000000" or _date_ge(close_dt, today)
    ):
        errors.append(_failure("E3007", "Close date in past", "WARN"))

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected legacy validation failure is blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
